let ownerBranch='Todas';
const branchBeforeRender=render,branchBeforeSaveIntake=saveIntake,branchBeforeReceive=receiveGarment,branchBeforeStaffCard=staffCard,branchBeforeMemberCard=memberCard,branchBeforeOwnerData=ownerData,branchBeforeReceptionCard=receptionCard;
function knownBranch(value){return Boolean(value&&value!=='Por confirmar'&&value!=='Sin sede')}
function responsibleBranch(r){return r.responsibleBranch||r.branch||'Por confirmar'}
function branchNames(){return [...new Set([...staffBranches.slice(1),...Object.values(state.staffProfiles||{}).map(p=>p.branch),...state.repairs.map(responsibleBranch)].filter(knownBranch))]}
function branchOptions(value,placeholder='Elige una sede'){return `<option value="">${placeholder}</option>`+branchNames().map(b=>`<option value="${esc(b)}" ${b===value?'selected':''}>${esc(b)}</option>`).join('')}
function branchMatches(r){return ownerBranch==='Todas'||(ownerBranch==='Sin sede'?!knownBranch(responsibleBranch(r)):responsibleBranch(r)===ownerBranch)}
function setOwnerBranch(value){ownerBranch=value;render()}
function branchFilter(){return `<section class="branch-filter"><label for="owner-branch">${icon('location')} Sede responsable<select id="owner-branch" onchange="setOwnerBranch(this.value)"><option>Todas</option>${branchNames().map(b=>`<option ${ownerBranch===b?'selected':''}>${esc(b)}</option>`).join('')}<option ${ownerBranch==='Sin sede'?'selected':''}>Sin sede</option></select></label><p>Filtra por el local que responde al cliente, aunque la prenda esté en otro lugar.</p></section>`}
function ownerBranchSummary(){const rows=branchBeforeOwnerData().repairs,names=branchNames();if(rows.some(r=>!knownBranch(responsibleBranch(r))))names.push('Sin sede');return `<section class="branch-summary"><h2>${icon('location')} Las sedes del taller</h2><p>Cada pedido conserva su sede hasta la entrega al cliente.</p><div>${names.map(b=>{const repairs=rows.filter(r=>(b==='Sin sede'?!knownBranch(responsibleBranch(r)):responsibleBranch(r)===b)&&r.stage!=='delivered');return `<button onclick="openBranchReception(this.dataset.branch)" data-branch="${esc(b)}"><strong>${esc(b)}</strong><span>${repairs.length} ${repairs.length===1?'prenda activa':'prendas activas'}</span></button>`}).join('')}</div></section>`}
function openBranchReception(branch){ownerBranch=branch;ownerNavigate('reception')}
function initBranches(){initWorkScope();for(const r of state.repairs)r.responsibleBranch||=r.branch||'Por confirmar';if(typeof RapicosturaBranches!=='undefined'){RapicosturaBranches.extend(state.branchCatalog);RapicosturaBranches.extend(branchNames());state.branchCatalog=[...RapicosturaBranches.sites];for(const name of RapicosturaBranches.sites)if(!staffBranches.includes(name))staffBranches.push(name)}else for(const p of Object.values(state.staffProfiles||{}))if(knownBranch(p.branch)&&!staffBranches.includes(p.branch))staffBranches.push(p.branch)}
function chooseStaffBranch(name=currentPerson){if(currentPerson!=='Dueña'&&name!==currentPerson)return;const p=staffProfile(name);modal('Sede de referencia','<form id="branch-profile-form"><label class="field">Sede de referencia<select id="branch-profile-value" required>'+branchOptions(p.branch)+'</select></label><div class="modalactions"><button type="button" class="btn" onclick="dialog.close()">Volver</button><button class="btn primary">Guardar sede</button></div></form>');document.getElementById('branch-profile-form').onsubmit=e=>{e.preventDefault();const value=document.getElementById('branch-profile-value').value;if(!branchNames().includes(value))return;p.branch=value;dialog.close();save(name+' actualizó su sede de referencia a '+value+'.')}}
staffCard=function(p){if(ownerBranch!=='Todas'&&(ownerBranch==='Sin sede'?knownBranch(p.branch):p.branch!==ownerBranch))return '';return branchBeforeStaffCard(p).replace('</section>','<button class="branch-assign" onclick="chooseStaffBranch(\''+esc(p.name)+'\')">Asignar sede</button></section>')};
memberCard=function(name){const p=staffProfile(name);if(ownerBranch!=='Todas'&&!ownerData().repairs.some(r=>holder(r.id)===name)&&(ownerBranch==='Sin sede'?knownBranch(p.branch):p.branch!==ownerBranch))return '';return branchBeforeMemberCard(name)};
receiveGarment=function(keep=false){if(!staffProfile(currentPerson).canReceive){toast('La dueña debe habilitarte para recibir prendas en el local.');return}branchBeforeReceive(keep===true);const select=document.getElementById('intake-branch');if(select&&intakeDraft){select.innerHTML=branchOptions(intakeDraft.branch||staffProfile(currentPerson).branch);select.required=true;select.closest('label').firstChild.textContent='Sede responsable del cliente'}};
saveIntake=function(){if(!intakeDraft||!branchNames().includes(intakeDraft.branch)){toast('Elige la sede que recibe al cliente.');return}const branch=intakeDraft.branch;if(!knownBranch(staffProfile(currentPerson).branch))staffProfile(currentPerson).branch=branch;branchBeforeSaveIntake()};
ownerData=function(){const d=branchBeforeOwnerData();if(ownerBranch==='Todas')return d;return {repairs:d.repairs.filter(branchMatches),agreements:d.agreements.filter(a=>a.repairIds.some(id=>{const r=d.repairs.find(r=>r.id===id);return r&&branchMatches(r)}))}};
receptionRecords=function(){return state.repairs.filter(r=>r.receivedBy&&(currentPerson==='Dueña'?branchMatches(r):r.receivedBy===currentPerson)).sort((a,b)=>(b.receivedAt||0)-(a.receivedAt||0))};
receptionCard=function(r){return branchBeforeReceptionCard(r).replace('</em>','</em><small>Sede responsable: '+esc(responsibleBranch(r))+'</small>')};
function canReview(r){return currentPerson!=='Dueña'&&staffProfile(currentPerson).canReceive&&knownBranch(staffProfile(currentPerson).branch)&&staffProfile(currentPerson).branch===responsibleBranch(r)}
function openQuality(id){const r=state.repairs.find(r=>r.id===id);if(!r||!canReview(r)||r.stage!=='review')return;modal('Revisar calidad · '+esc(r.id),'<form id="quality-form"><p>'+esc(r.garment)+' · '+esc(r.task)+'</p><p>'+esc(r.instructions||'')+'</p><p>Revisa físicamente la prenda antes de aprobar.</p><label class="choose-row"><input id="quality-present" type="checkbox" required><span>Puedo revisar esta prenda aquí y ahora.</span></label><label class="choose-row"><input id="quality-correct" type="checkbox" required><span>El arreglo, las costuras y el acabado cumplen lo acordado.</span></label><div class="modalactions"><button class="btn" type="button" onclick="requestCorrection(\''+id+'\')">Necesita corrección</button><button class="btn primary">Aprobar calidad</button></div></form>');document.getElementById('quality-form').onsubmit=e=>{e.preventDefault();finishQuality(id,document.getElementById('quality-present').checked&&document.getElementById('quality-correct').checked)}}
function finishQuality(id,checked){const r=state.repairs.find(r=>r.id===id);if(!r||!canReview(r)||r.stage!=='review'||!checked)return;r.stage='ready';r.reviewedBy=currentPerson;r.reviewedAt=Date.now();r.issue='';dialog.close();save(currentPerson+' aprobó la calidad de '+id+'. Lista para el cliente.')}
function requestCorrection(id){const r=state.repairs.find(r=>r.id===id);if(!r||!canReview(r)||r.stage!=='review')return;modal('¿Qué debe corregirse?','<form id="quality-correction"><label class="field">Detalle de la corrección<textarea id="quality-note" maxlength="500" required></textarea></label><button class="btn primary">Guardar corrección</button></form>');document.getElementById('quality-correction').onsubmit=e=>{e.preventDefault();const note=document.getElementById('quality-note').value.trim();if(!note||!canReview(r)||r.stage!=='review')return;r.stage='working';r.issue=note;dialog.close();save(currentPerson+' pidió corregir '+id+': '+note)}}
function deliverToClient(id){const r=state.repairs.find(r=>r.id===id);if(!r||!canReview(r)||r.stage!=='ready')return;modal('Entregar al cliente','<p>¿Ya devolviste '+esc(r.garment)+' a '+esc(r.client)+'?</p><div class="modalactions">'+button('Todavía no','dialog.close()')+button('Sí, entregada al cliente',"confirmClientDelivery('"+id+"')",true)+'</div>')}
function confirmClientDelivery(id){const r=state.repairs.find(r=>r.id===id);if(!r||!canReview(r)||r.stage!=='ready')return;r.stage='delivered';r.deliveredBy=currentPerson;r.deliveredAt=Date.now();dialog.close();save(currentPerson+' entregó '+id+' al cliente.')}
function qualityQueue(){const rows=state.repairs.filter(r=>canReview(r)&&['review','ready'].includes(r.stage));return rows.length?'<section class="profile-sheet"><h2>Calidad y entrega al cliente</h2>'+rows.map(r=>'<div class="branch-return-row"><strong>'+esc(r.garment)+' · '+r.id+'</strong><p>'+repairLabels[r.stage]+'</p>'+button(r.stage==='review'?'Revisar calidad':'Entregar al cliente',r.stage==='review'?"openQuality('"+r.id+"')":"deliverToClient('"+r.id+"')",true,'check')+'</div>').join('')+'</section>':''}
render=function(){initBranches();branchBeforeRender();if(currentPerson==='Dueña'&&['overview','inicio','members','reception','movements','attention'].includes(page)){const heading=main.querySelector('.owner-heading,.greeting');heading?.insertAdjacentHTML('afterend',branchFilter());if(['overview','inicio'].includes(page))main.querySelector('.owner-kpis')?.insertAdjacentHTML('afterend',ownerBranchSummary())}else if(currentPerson!=='Dueña'&&page==='reception'){main.querySelector('.greeting')?.insertAdjacentHTML('afterend',qualityQueue())}};
render();
